(()=>{const addCss=(href,id)=>{if(document.getElementById(id)||document.querySelector(`link[href*="${href.split('?')[0]}"]`))return;const l=document.createElement('link');l.id=id;l.rel='stylesheet';l.href=href;document.head.appendChild(l)};const load=(src)=>new Promise((resolve,reject)=>{const s=document.createElement('script');s.src=src;s.defer=true;s.onload=resolve;s.onerror=reject;document.head.appendChild(s)});const mount=()=>{const old=document.querySelector('.nav');if(!old)return;old.outerHTML=`<header class="site-header" id="site-header"><a class="site-header__brand" href="#main" aria-label="Paranoir Studio, retour en haut">Paranoir Studio</a><nav class="site-header__nav" aria-label="Navigation principale"><div class="site-header__links"><a class="site-header__link" href="#approche">Notre approche</a><a class="site-header__link" href="#strategie">La stratégie</a><a class="site-header__link" href="#deploiement">Le déploiement</a><a class="site-header__link" href="#projets">Les projets</a><a class="site-header__link" href="#realisations">Réalisations</a><a class="site-header__link" href="#studio">Le studio</a><a class="site-header__link" href="#faq">FAQ</a></div></nav><div class="site-header__actions"><button class="site-header__intent" type="button" data-open-intent aria-expanded="false" aria-controls="intent-modal">Vous voulez ?</button><a class="site-header__cta" href="#test">Faire le test gratuit</a><button class="site-header__menu-toggle" id="menuToggle" type="button" aria-label="Ouvrir le menu" aria-expanded="false" aria-controls="mobileMenu"><span></span><span></span><span></span></button></div></header>`;const page=document.querySelector('.page');const main=document.getElementById('main');if(!page||!main)return;const backdrop=document.createElement('div');backdrop.className='site-mobile-menu__backdrop';backdrop.id='mobileMenuBackdrop';page.insertBefore(backdrop,main);const mobile=document.createElement('aside');mobile.className='site-mobile-menu';mobile.id='mobileMenu';mobile.setAttribute('aria-label','Menu mobile');mobile.innerHTML=`<nav class="site-mobile-menu__links"><a href="#approche">Notre approche</a><a href="#strategie">La stratégie</a><a href="#deploiement">Le déploiement</a><a href="#projets">Les projets</a><a href="#realisations">Réalisations</a><a href="#studio">Le studio</a><a href="#faq">FAQ</a></nav><div class="site-mobile-menu__actions"><button class="site-header__intent" type="button" data-open-intent aria-expanded="false" aria-controls="intent-modal">Vous voulez ?</button><a class="site-header__cta" href="#test">Faire le test gratuit</a></div>`;page.insertBefore(mobile,main);const dlg=document.createElement('dialog');dlg.className='intent-modal';dlg.id='intent-modal';dlg.setAttribute('aria-labelledby','intent-modal-title');dlg.innerHTML=`<div class="intent-modal__inner"><div class="intent-modal__top"><div><p class="intent-modal__eyebrow">Choisir un parcours</p><h2 id="intent-modal-title">Vous voulez ?</h2><p class="intent-modal__intro">Choisissez le type d’accompagnement qui correspond le mieux à votre situation.</p></div><button class="intent-modal__close" id="intentModalClose" type="button" aria-label="Fermer la fenêtre">×</button></div><div class="intent-modal__options"><a class="intent-option" href="#strategie"><span class="intent-option__num">01</span><h3>Revoir votre stratégie et votre image de marque en ligne</h3><p>Clarifier votre positionnement, votre offre et votre message, puis les déployer sur votre site, votre réseau social principal et Google Business Profile.</p><span class="intent-option__arrow" aria-hidden="true">→</span></a><a class="intent-option" href="/formation"><span class="intent-option__num">02</span><h3>Former votre équipe en interne</h3><p>Transmettre à votre équipe une méthode claire pour structurer vos offres, vos messages et votre communication dans la durée.</p><span class="intent-option__arrow" aria-hidden="true">→</span></a><a class="intent-option" href="/consulting"><span class="intent-option__num">03</span><h3>Être conseillé pour mieux piloter</h3><p>Bénéficier d’un regard extérieur pour cadrer une décision, structurer une offre, arbitrer un projet ou mieux diriger votre communication.</p><span class="intent-option__arrow" aria-hidden="true">→</span></a></div></div>`;document.body.appendChild(dlg);const anchors=[['approche','.statement'],['test','#prediagnostic'],['strategie','#reservation'],['deploiement','#reservation'],['projets','#comparatif-offres'],['realisations','.realisations'],['studio','.about'],['faq','.faq']];anchors.forEach(([id,selector])=>{const target=document.querySelector(selector);if(!target)return;if(target.id===id)return;const a=document.createElement('span');a.className='nav-anchor';a.id=id;target.parentNode.insertBefore(a,target)});document.querySelectorAll('a[href="#prediagnostic"]').forEach(a=>a.setAttribute('href','#test'))};addCss('/assets/css/navigation-v2.css?v=1','navigation-v2-css');addCss('/assets/css/manifesto-v2.css?v=1','manifesto-v2-css');if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',mount,{once:true});else mount();load('/assets/js/site.js?v=5').then(()=>load('/assets/js/navigation-v2.js?v=3')).then(()=>load('/assets/js/hero-deployment-v2.js?v=4')).then(()=>load('/assets/js/manifesto-v2.js?v=1')).catch(console.error)})();